def choose_move(observation):
    def g(obj, key, default=None):
        if isinstance(obj, dict):
            return obj.get(key, default)
        return default

    def first_present(d, keys):
        for k in keys:
            v = g(d, k, None)
            if v is not None:
                return v
        return None

    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def as_pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [v[0], v[1]]
        if isinstance(v, dict):
            x = first_present(v, ["x", "col", "c", "px"])
            y = first_present(v, ["y", "row", "r", "py"])
            if is_num(x) and is_num(y):
                return [x, y]
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_step(v):
        if v > 1:
            return 1
        if v < -1:
            return -1
        return v

    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def flatten_positions(value):
        out = []
        if value is None:
            return out
        if isinstance(value, dict):
            p = as_pos(value)
            if p is not None:
                out.append(p)
            else:
                for vv in value.values():
                    out.extend(flatten_positions(vv))
        elif isinstance(value, (list, tuple)):
            if len(value) >= 2 and is_num(value[0]) and is_num(value[1]):
                out.append([value[0], value[1]])
            else:
                for item in value:
                    out.extend(flatten_positions(item))
        return out

    def get_self_pos(obs):
        keys = ["position", "pos", "agent_pos", "self_pos", "player_pos", "location", "loc"]
        p = as_pos(first_present(obs, keys))
        if p is not None:
            return p
        me = first_present(obs, ["agent", "self", "player", "me", "unit"])
        if isinstance(me, dict):
            p = as_pos(me)
            if p is not None:
                return p
        return [0, 0]

    def get_grid(obs):
        for k in ["grid", "map", "board", "terrain", "cells"]:
            v = g(obs, k, None)
            if isinstance(v, list):
                return v
        return None

    def cell_at(grid, x, y):
        if grid is None:
            return None
        if y < 0 or y >= len(grid):
            return None
        row = grid[y]
        if not isinstance(row, list) or x < 0 or x >= len(row):
            return None
        return row[x]

    def passable(grid, x, y):
        c = cell_at(grid, x, y)
        if c is None:
            return True
        if isinstance(c, dict):
            if g(c, "blocked", False) or g(c, "wall", False) or g(c, "obstacle", False):
                return False
            t = g(c, "type", None)
            if t in ("wall", "obstacle", "blocked", "water"):
                return False
            return True
        if isinstance(c, str):
            return c not in ("#", "X", "x", "W", "wall", "blocked", "obstacle")
        if isinstance(c, (int, float)):
            return c not in (1, 9)
        return True

    obs_type = first_present(observation, ["type", "game_type", "mode", "scenario", "name"])
    obs_type = obs_type if isinstance(obs_type, str) else ""

    me = get_self_pos(observation)
    grid = get_grid(observation)

    resources = []
    for k in ["resources", "resource", "items", "coins", "food", "targets", "goal", "goals"]:
        resources.extend(flatten_positions(g(observation, k, None)))

    enemies = []
    for k in ["enemies", "enemy", "opponents", "opponent", "pursuers", "evaders", "units"]:
        enemies.extend(flatten_positions(g(observation, k, None)))

    territories = []
    for k in ["territories", "territory", "cells_owned", "zones", "frontier"]:
        territories.extend(flatten_positions(g(observation, k, None)))

    # Remove self duplicates if present
    def uniq_near(lst):
        out = []
        seen = set()
        for p in lst:
            key = (p[0], p[1])
            if key not in seen and key != (me[0], me[1]):
                seen.add(key)
                out.append(p)
        return out

    resources = uniq_near(resources)
    enemies = uniq_near(enemies)
    territories = uniq_near(territories)

    # Infer objective
    wants_avoid = False
    wants_chase = False
    if "evad" in obs_type or "avoid" in obs_type or "runner" in obs_type:
        wants_avoid = True
    if "pursuit" in obs_type or "pursu" in obs_type or "chase" in obs_type or "hunter" in obs_type:
        wants_chase = True
    role = first_present(observation, ["role", "agent_role", "team_role", "stance"])
    if isinstance(role, str):
        r = role.lower()
        if "evad" in r or "runner" in r or "flee" in r:
            wants_avoid = True
        if "purs" in r or "hunt" in r or "chase" in r:
            wants_chase = True

    # Choose target
    target = None
    target_list = []

    if resources:
        target_list = resources
    elif territories:
        target_list = territories
    elif enemies and wants_chase:
        target_list = enemies
    elif enemies and wants_avoid:
        target_list = enemies

    if target_list:
        target = min(target_list, key=lambda p: manhattan(me, p))

    # Candidate moves
    candidates = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx = me[0] + dx
            ny = me[1] + dy
            if passable(grid, nx, ny):
                candidates.append([dx, dy])

    if not candidates:
        return [0, 0]

    # Score moves
    best = [0, 0]
    best_score = None

    nearest_enemy = min(enemies, key=lambda p: manhattan(me, p)) if enemies else None
    nearest_resource = min(resources, key=lambda p: manhattan(me, p)) if resources else None
    nearest_territory = min(territories, key=lambda p: manhattan(me, p)) if territories else None

    for dx, dy in candidates:
        nx = me[0] + dx
        ny = me[1] + dy
        score = 0.0

        # Prefer progress toward target
        if target is not None:
            d0 = manhattan(me, target)
            d1 = manhattan([nx, ny], target)
            score += (d0 - d1) * 10.0

        # Resource collection bias
        if nearest_resource is not None:
            score += (manhattan(me, nearest_resource) - manhattan([nx, ny], nearest_resource)) * 6.0

        # Territory control bias
        if nearest_territory is not None:
            score += (manhattan(me, nearest_territory) - manhattan([nx, ny], nearest_territory)) * 4.0

        # Pursuit/evasion
        if nearest_enemy is not None:
            d0 = manhattan(me, nearest_enemy)
            d1 = manhattan([nx, ny], nearest_enemy)
            if wants_avoid:
                score += (d1 - d0) * 12.0
                if d1 == 0:
                    score -= 1000.0
            elif wants_chase:
                score += (d0 - d1) * 12.0
            else:
                # Default: slightly keep distance unless resources exist
                score += (d1 - d0) * 1.0

        # Prefer staying put only when no better info
        if dx == 0 and dy == 0:
            score -= 0.25

        # Mild center-seeking if no target
        if target is None and grid is not None and isinstance(grid, list) and len(grid) > 0 and isinstance(grid[0], list) and len(grid[0]) > 0:
            cx = (len(grid[0]) - 1) / 2.0
            cy = (len(grid) - 1) / 2.0
            score -= (abs(nx - cx) + abs(ny - cy)) * 0.01

        if best_score is None or score > best_score:
            best_score = score
            best = [dx, dy]

    return best

